/**
 * The asset manifest (SRS 4.3, RF-3D-01): which processed GLB to use for each
 * team and season and for each circuit layout, and under which licence.
 *
 * The manifest is generated by tools/assets/build_assets.py and versioned; the
 * GLB files it points to live under /manager-assets/ and are served by nginx
 * (GitHub release downloads do not send CORS headers). A team or circuit with
 * no entry - or whose files were never built on this machine - falls back to
 * the procedural model of its era (RF-3D-02).
 *
 * Public builds (REACT_APP_PUBLIC_BUILD=true) leave out every asset that is not
 * known to be safe: `riskRipped` true, or not yet verified (null) (SRS 3.3, 7.3).
 */

import manifest from "../../data/manager-assets.json";

const publicBuild = () => process.env.REACT_APP_PUBLIC_BUILD === "true";

/** May this asset be shown in this build? */
export const allowed = (entry, { isPublic = publicBuild() } = {}) => Boolean(entry) && (!isPublic || entry.riskRipped === false);

const base = (data = manifest) => `${process.env.PUBLIC_URL || ""}${data.baseUrl || "/manager-assets/"}`;

/** Absolute URL of a manifest path, versioned by the manifest hash so a new build never reads a stale file. */
export const assetUrl = (path, data = manifest) => `${base(data)}${path}?v=${data.hash || "0"}`;

export const manifestHash = () => manifest.hash || "0";

/** The processed car of one team in one season, or null. */
export const carAssetFor = (season, teamRef, options = {}, data = manifest) => {
  const entry = (data.cars || []).find((car) => car.season === Number(season) && car.teamRef === teamRef);
  return allowed(entry, options) ? entry : null;
};

/**
 * The processed circuit for a race: by the f1db layout id the season pack
 * carries, or by circuit and year for seasons without a pack.
 */
export const circuitAssetFor = ({ layoutId = null, circuitRef = null, layoutRef = null, splineId = null, year = null } = {}, options = {}, data = manifest) => {
  const list = data.circuits || [];
  const entry =
    (splineId && list.find((circuit) => circuit.splineId === splineId)) ||
    (layoutId && list.find((circuit) => circuit.layoutId === layoutId)) ||
    list.find((circuit) => (circuit.circuitRef === circuitRef || circuit.layoutRef === layoutRef) && year !== null && circuit.validFrom <= year && year <= circuit.validTo) ||
    null;
  return allowed(entry, options) ? entry : null;
};

/** Every asset a season shows, with author and licence, for the showroom credits (RF-3D-06, criterio 7.2). */
export const creditsFor = (season, data = manifest) =>
  (data.cars || [])
    .filter((car) => car.season === Number(season))
    .map((car) => ({ teamRef: car.teamRef, chassis: car.chassis, author: car.author, license: car.license, source: car.source, status: car.status }));

/** Which LOD a car should show at a distance (metres from the camera). */
export const LOD_DISTANCES = [0, 28, 80];
export const lodForDistance = (distance) => (distance >= LOD_DISTANCES[2] ? 2 : distance >= LOD_DISTANCES[1] ? 1 : 0);

export default manifest;
